begin;
-- A31 (3 Oct 2026): videos are organised in 35 groups. Additive only.
--   media_groups              one row per group: names in the 9 languages, the categories it is
--                             made of, and its representative video for a learner without history
--                             (level A, level B, all levels)
--   media.group_id            the one main group of a media
--   tinder_word_distractors   per video (its key word): the other key words of the same group
--                             and level that may be shown as the WRONG word on a one-word Tinder card
--                             (same part of speech first)
-- The rows are written by the guarded data script of the run (and-again-content
-- runs/a31_20261003); this file only creates the objects.

create table if not exists public.media_groups (
  id bigint primary key,
  name jsonb not null,
  source_category_ids bigint[] not null,
  rep_media_a bigint references public.media(id) on delete set null,
  rep_media_b bigint references public.media(id) on delete set null,
  rep_media_all bigint references public.media(id) on delete set null
);

alter table public.media_groups enable row level security;
drop policy if exists "Media groups are viewable by everyone" on public.media_groups;
create policy "Media groups are viewable by everyone" on public.media_groups for select using (true);
revoke all on public.media_groups from anon, authenticated;
grant select on public.media_groups to anon, authenticated;

alter table public.media add column if not exists group_id bigint references public.media_groups(id) on delete set null;
create index if not exists media_group_id_idx on public.media(group_id);

create table if not exists public.tinder_word_distractors (
  media_id bigint primary key references public.media(id) on delete cascade,
  concept_id bigint not null references public.word_concepts(id) on delete cascade,
  group_id bigint not null references public.media_groups(id) on delete cascade,
  level text not null check (level in ('A', 'B')),
  distractor_concept_ids bigint[] not null,
  -- only for a video with fewer than 5 options: key words of the same group at the OTHER level
  fallback_concept_ids bigint[] not null default '{}'
);
create index if not exists tinder_word_distractors_concept_idx on public.tinder_word_distractors(concept_id);

alter table public.tinder_word_distractors enable row level security;
drop policy if exists "Tinder word distractors are viewable by everyone" on public.tinder_word_distractors;
create policy "Tinder word distractors are viewable by everyone" on public.tinder_word_distractors for select using (true);
revoke all on public.tinder_word_distractors from anon, authenticated;
grant select on public.tinder_word_distractors to anon, authenticated;
-- A31 data write (guarded). Run after migration 20261003210000_a31_media_groups.sql.

do $$ begin
  if (select count(*) from public.media_groups) <> 0 then raise exception 'media_groups is not empty'; end if;
  if (select count(*) from public.tinder_word_distractors) <> 0 then raise exception 'tinder_word_distractors is not empty'; end if;
  if (select count(*) from public.media where group_id is not null) <> 0 then raise exception 'media.group_id already set'; end if;
  if (select count(*) from public.media) <> 6205 then raise exception 'media count changed since the snapshot'; end if;
  if (select count(*) from public.media_categories) <> 6205 then raise exception 'media_categories changed since the snapshot'; end if;
end $$;
update public.media m set group_id = g.id from public.media_categories mc join public.media_groups g on mc.category_id = any(g.source_category_ids) where mc.media_id = m.id;
do $$ begin
  if (select count(*) from public.media_groups) <> 35 then raise exception 'groups <> 35'; end if;
  if (select count(*) from public.media where group_id is null) <> 0 then raise exception 'media without group'; end if;
  if (select count(*) from public.media where media_type = 'video') <> 3034 then raise exception 'video count'; end if;
  if (select count(*) from public.tinder_word_distractors) <> 3034 then raise exception 'distractor rows'; end if;
  if exists (select 1 from public.tinder_word_distractors d join public.media m on m.id = d.media_id where m.group_id <> d.group_id or m.media_type <> 'video') then raise exception 'distractor group mismatch'; end if;
  if exists (select 1 from public.tinder_word_distractors d where not exists (select 1 from public.exercises e where e.media_id = d.media_id and e.concept_id = d.concept_id and e.exercise_type_id = case d.level when 'A' then 74 else 75 end)) then raise exception 'key word / level mismatch'; end if;
  if exists (select 1 from public.tinder_word_distractors d, unnest(d.distractor_concept_ids || d.fallback_concept_ids) c where not exists (select 1 from public.word_concepts w where w.id = c)) then raise exception 'unknown concept in a list'; end if;
  if exists (select 1 from public.tinder_word_distractors d join public.concept_media cm on cm.media_id = d.media_id where cm.concept_id = any(d.distractor_concept_ids || d.fallback_concept_ids)) then raise exception 'a list holds a word linked to the same media'; end if;
  if exists (select 1 from public.media_groups g join public.media m on m.id in (g.rep_media_a, g.rep_media_b, g.rep_media_all) where m.group_id <> g.id or m.media_type <> 'video') then raise exception 'representative outside its group'; end if;
end $$;

do $$ begin raise exception 'DRY RUN OK: groups %, media grouped %, lists %', (select count(*) from public.media_groups), (select count(*) from public.media where group_id is not null), (select count(*) from public.tinder_word_distractors); end $$;
commit;
